impl Document {
    pub(crate) fn compare_td_event_mode_declaration(
        &self,
        other: &Document,
        a: &TDEventModeDeclaration,
        b: &TDEventModeDeclaration,
        path: &str,
    ) -> Result<(), String> {
        self.compare_td_event_vfb_port(other, a.base(), b.base(), path)?;
        if a.get_entry_mode_declaration_ref() != b.get_entry_mode_declaration_ref() {
            return Err(format!("{path}: ENTRY_MODE_DECLARATION_REF mismatch"));
        }
        if a.get_exit_mode_declaration_ref() != b.get_exit_mode_declaration_ref() {
            return Err(format!("{path}: EXIT_MODE_DECLARATION_REF mismatch"));
        }
        if a.get_mode_declaration_ref() != b.get_mode_declaration_ref() {
            return Err(format!("{path}: MODE_DECLARATION_REF mismatch"));
        }
        if a.get_td_event_mode_declaration_type() != b.get_td_event_mode_declaration_type() {
            return Err(format!("{path}: TD_EVENT_MODE_DECLARATION_TYPE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_td_event_operation(
        &self,
        other: &Document,
        a: &TDEventOperation,
        b: &TDEventOperation,
        path: &str,
    ) -> Result<(), String> {
        self.compare_td_event_vfb_port(other, a.base(), b.base(), path)?;
        if a.get_operation_ref() != b.get_operation_ref() {
            return Err(format!("{path}: OPERATION_REF mismatch"));
        }
        if a.get_td_event_operation_type() != b.get_td_event_operation_type() {
            return Err(format!("{path}: TD_EVENT_OPERATION_TYPE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_td_event_trigger(
        &self,
        other: &Document,
        a: &TDEventTrigger,
        b: &TDEventTrigger,
        path: &str,
    ) -> Result<(), String> {
        self.compare_td_event_vfb_port(other, a.base(), b.base(), path)?;
        if a.get_trigger_ref() != b.get_trigger_ref() {
            return Err(format!("{path}: TRIGGER_REF mismatch"));
        }
        if a.get_td_event_trigger_type() != b.get_td_event_trigger_type() {
            return Err(format!("{path}: TD_EVENT_TRIGGER_TYPE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_td_event_variable_data_prototype(
        &self,
        other: &Document,
        a: &TDEventVariableDataPrototype,
        b: &TDEventVariableDataPrototype,
        path: &str,
    ) -> Result<(), String> {
        self.compare_td_event_vfb_port(other, a.base(), b.base(), path)?;
        if a.get_data_element_ref() != b.get_data_element_ref() {
            return Err(format!("{path}: DATA_ELEMENT_REF mismatch"));
        }
        if a.get_td_event_variable_data_prototype_type()
            != b.get_td_event_variable_data_prototype_type()
        {
            return Err(format!(
                "{path}: TD_EVENT_VARIABLE_DATA_PROTOTYPE_TYPE mismatch"
            ));
        }
        Ok(())
    }

    pub(crate) fn compare_td_event_vfb(
        &self,
        other: &Document,
        a: &TDEventVfb,
        b: &TDEventVfb,
        path: &str,
    ) -> Result<(), String> {
        self.compare_timing_description_event(other, a.base(), b.base(), path)?;
        if a.get_component_i_ref() != b.get_component_i_ref() {
            return Err(format!("{path}: COMPONENT_I_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_td_event_vfb_port(
        &self,
        other: &Document,
        a: &TDEventVfbPort,
        b: &TDEventVfbPort,
        path: &str,
    ) -> Result<(), String> {
        self.compare_td_event_vfb(other, a.base(), b.base(), path)?;
        if a.get_is_external() != b.get_is_external() {
            return Err(format!("{path}: IS_EXTERNAL mismatch"));
        }
        if a.get_port_ref() != b.get_port_ref() {
            return Err(format!("{path}: PORT_REF mismatch"));
        }
        if a.get_port_prototype_blueprint_ref() != b.get_port_prototype_blueprint_ref() {
            return Err(format!("{path}: PORT_PROTOTYPE_BLUEPRINT_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_td_event_vfb_reference(
        &self,
        other: &Document,
        a: &TDEventVfbReference,
        b: &TDEventVfbReference,
        path: &str,
    ) -> Result<(), String> {
        self.compare_td_event_vfb(other, a.base(), b.base(), path)?;
        if a.get_referenced_td_event_vfb_ref() != b.get_referenced_td_event_vfb_ref() {
            return Err(format!("{path}: REFERENCED_TD_EVENT_VFB_REF mismatch"));
        }
        Ok(())
    }
}
